import{z as l,x as i,o as r,c as B,q as E,j as s,D as t,d as a,s as d,S as p,b as o}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"双端队列","description":"","frontmatter":{"title":"双端队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deque.md","filePath":"cs/deque.md","lastUpdated":1791413859000}'),u={name:"cs/deque.md"};function A(c,e,h,m,_,f){const n=i("Mermaid");return r(),B("div",null,[e[2]||(e[2]=E('<h1 id="双端队列" tabindex="-1">双端队列 <a class="header-anchor" href="#双端队列" aria-label="Permalink to &quot;双端队列&quot;">​</a></h1><div class="epigraph"><p>两端都能进、两端都能出；栈和队列是它在操作集上的两个真子集。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/queue-buffer">上一课</a>钉了 FIFO：尾进头出，并声明双端「主干不提前」。栈是一端 LIFO。本课不重讲环形模运算。缺口是 deque 合同：<code>push_front</code>/<code>push_back</code>/<code>pop_front</code>/<code>pop_back</code> 均摊还或最坏 \\(\\Theta(1)\\)，用来做滑动窗口、两端生长的工作列。表示可以是双向链表，也可以是后课环形数组的两端指针。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只提供队列则无法在队头插入；只提供栈则无法在底端取。算法里「最新的从一端进、过期的从另一端丢」（单调队列）需要两侧。缺口不是新的节点类型，而是<strong>把序列的两端都暴露成 \\(O(1)\\) 端点操作</strong>，中间按下标仍可昂贵。</p><p><span class="marginnote">直觉类比：deque 像一条两端都开了门的走廊——元素从前门或后门进出都行；栈是只开后门的走廊（后进先出），队列是后门进、前门出的走廊（先进先出）。合同上看，栈与队列不过是把 deque 的四个门各关掉两个剩下的用法。</span></p><p>空时四端操作无定义或失败；实现不得把「头超过尾」留成未定义环。</p><p><span class="marginnote">STL deque 常用分块数组，使两端增长不必整表复制。本课先钉合同；块列是表示优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链表表示：双向表的哨兵两侧即两端，四个操作都是改常数条边。数组表示：头尾两个下标，向左增长时 <code>head = (head-1+cap) mod cap</code>——这已是环形缓冲的雏形，下一课专收。</p>',10)),(r(),s(p,null,{default:t(()=>[d(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20PF%5B%22pop_front%22%5D%20--%3E%20SEQ%5B%22%E5%BA%8F%E5%88%97%22%5D%0A%20%20SEQ%20--%3E%20PB%5B%22pop_back%22%5D%0A%20%20PUSHF%5B%22push_front%22%5D%20--%3E%20SEQ%0A%20%20PUSHB%5B%22push_back%22%5D%20--%3E%20SEQ%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("p",null,[a("栈 = 只开同一端的 push/pop。队列 = 只开 "),o("code",null,"push_back"),a(" + "),o("code",null,"pop_front"),a("。合同包含关系让测试用例可以共享。")],-1)),e[4]||(e[4]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=o("p",null,[a("与"),o("a",{href:"/cs/locality-principle"},"局部性原理"),a("：链表 deque 两端操作仍是指针追逐；要扫中间更差。高频滑动窗口若元素连续，数组环形更好。本课允许两种，后课把环形从队列里提出来当独立表示。")],-1)),e[6]||(e[6]=o("p",null,"单调队列是 deque 两端各司其职的典型用户，两端动作分工明确：",-1)),(r(),s(p,null,{default:t(()=>[d(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E5%85%83%E7%B4%A0%E5%88%B0%E8%BE%BE%E7%AA%97%E5%8F%A3%E5%8F%B3%E7%AB%AF%22%5D%20--%3E%20CMP%5B%22%E4%BB%8E%E9%98%9F%E5%B0%BE%E5%BC%B9%E5%87%BA%E6%AF%94%E5%AE%83%E5%B0%8F%E7%9A%84%E4%B8%8B%E6%A0%87%22%5D%0A%20%20CMP%20--%3E%20IN%5B%22push_back%EF%BC%9A%E6%96%B0%E4%B8%8B%E6%A0%87%E5%85%A5%E9%98%9F%E5%B0%BE%22%5D%0A%20%20OLD%5B%22%E9%98%9F%E5%A4%B4%E4%B8%8B%E6%A0%87%E6%BB%91%E5%87%BA%E7%AA%97%E5%8F%A3%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20OUT%5B%22pop_front%EF%BC%9A%E4%B8%A2%E6%8E%89%E8%BF%87%E6%9C%9F%E8%80%85%22%5D%0A%20%20QUERY%5B%22%E8%A6%81%E5%BD%93%E5%89%8D%E7%AA%97%E5%8F%A3%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%20--%3E%20PEEK%5B%22%E8%AF%BB%E9%98%9F%E5%A4%B4%EF%BC%8C%E4%B8%80%E6%AC%A1%E5%8D%B3%E7%AD%94%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=E('<p><span class="marginnote">数字实例：滑动窗口最大值里，每个元素至多 <code>push_back</code> 一次、至多被从队尾或队头弹掉一次，总操作不超过 \\(2n\\) 次，均摊 \\(\\Theta(1)\\)。若改成每个窗口重扫一遍取最大，就是 \\(n \\times k\\) 次——\\(n=10^6\\)、\\(k=1000\\) 时差出三个数量级。</span></p><p><span class="marginnote">常见误区：初学者容易以为「双端都能 \\(O(1)\\)」等于中间也能 \\(O(1)\\)。deque 的合同只钉两端，按下标访问中间在链表表示下是 \\(O(n)\\)；把随机访问当成免费能力，是性能分析里最晚被抓到的那口锅。</span></p><p>中间插入删除若也要 \\(\\Theta(1)\\)，调用方必须持有节点句柄，那是链表合同，不是下标 deque。混用会把随机访问假装成 \\(O(1)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入优先双端（两端按键），那是堆的变体。也不写无锁 deque。扩容数组在两端同时增长时复制规则更烦，摊还课用单端表扩张即可，不必先在这里证明。</p><p>后课默认：需要两侧端点用 deque。定长高性能缓冲把数组收成环，头尾追逐，下一课只谈那一种布局。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>deque 四端 \\(\\Theta(1)\\)；栈与队列是操作子集。</li><li>链表或环形数组都能表示；局部性偏向数组。</li><li>环形布局与满空区分是下一课。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 对双端队列的接口。</li></ul>',8))])}const F=l(u,[["render",A]]);export{b as __pageData,F as default};
